
create or replace function public.financial_budget_can(p_org uuid,p_entity uuid default null,p_center uuid default null,p_write boolean default false) returns boolean language sql stable security definer set search_path='pg_catalog','public' as $$select auth.uid() is not null and public.has_organization_permission(p_org,case when p_write then 'budget.edit' else 'budget.view' end) and public.financial_core_can(p_org,'financial_core.view') and exists(select 1 from public.organization_members m where m.organization_id=p_org and m.user_id=auth.uid() and m.status='ACTIVE');$$;
create or replace view public.financial_budget_operational_facts with(security_invoker=true) as
select l.id financial_line_id,e.id event_id,e.organization_id,e.entity_id,coalesce(l.cost_center_id,r.cost_center_id) cost_center_id,l.classification_id,c.classification_type,e.event_date,e.status,e.event_type,e.source_module,e.source_record_id,e.source_event_key,e.base_currency,l.currency source_currency,l.exchange_rate,l.base_amount raw_base_amount,l.metadata,null::text document_kind,null::text side,null::numeric recoverable_percent,1 sign,l.base_amount budget_base_amount,
case when e.entity_id is null and r.entity_id is null then 'ENTITY_ROUTE_REQUIRED' else null end source_issue,
case when e.status='ACTUAL' then l.base_amount else 0 end actual_base_amount,
case when e.status='COMMITTED' then l.base_amount else 0 end committed_base_amount
from public.financial_event_lines l join public.financial_events e on e.id=l.event_id join public.financial_classifications c on c.id=l.classification_id left join public.financial_budget_event_routes r on r.event_id=e.id
where e.status in('ACTUAL','COMMITTED') and e.event_type not in('SETTLEMENT','REVERSAL','TRANSFER') and l.cash_direction='NON_CASH' and c.classification_type in('REVENUE','OPEX','CAPEX','FINANCING','INVESTMENT');
create or replace function private.phase2d_event_weight(p_event uuid) returns numeric language sql stable security definer set search_path='pg_catalog','public' as $$select coalesce(sum(l.base_amount),0) from public.financial_event_lines l join public.financial_classifications c on c.id=l.classification_id where l.event_id=p_event and c.classification_type in('REVENUE','OPEX','CAPEX','FINANCING','INVESTMENT');$$;
create or replace function private.phase2d_plan_facts(p_plan uuid) returns table(financial_line_id uuid,event_id uuid,organization_id uuid,entity_id uuid,cost_center_id uuid,classification_type text,event_date date,fiscal_month integer,metric_status text,budget_line_id uuid,mapping_id uuid,actual_amount numeric,committed_amount numeric,unmapped_amount numeric,reason text,source_module text,source_record_id uuid,source_event_key text,base_currency text) language sql stable security definer set search_path='pg_catalog','public' as $$
with facts as(select f.*,o.plan_id,p.currency plan_currency,((extract(year from f.event_date)::int-extract(year from o.fiscal_start)::int)*12+extract(month from f.event_date)::int-extract(month from o.fiscal_start)::int+1) month_index from public.financial_budget_operational_facts f join public.financial_budget_plan_ownership o on o.organization_id=f.organization_id join public.budget_plans p on p.id=o.plan_id where o.plan_id=p_plan and(o.entity_id is null or o.entity_id=f.entity_id)and(o.cost_center_id is null or o.cost_center_id=f.cost_center_id)and f.event_date>=o.fiscal_start and f.event_date<o.fiscal_start+interval '1 year'),
matches as(select f.*,m.id selected_mapping,m.budget_line_id selected_line,case when f.source_issue is not null then f.source_issue when f.base_currency<>f.plan_currency then 'BASE_CURRENCY_MISMATCH' when m.id is null then 'NO_MAPPING' end unmapped_reason from facts f left join lateral(select m0.id,m0.budget_line_id from public.financial_budget_mappings m0 where m0.plan_id=p_plan and not exists(select 1 from public.financial_budget_retirements rr where rr.mapping_id=m0.id)and m0.classification_id=f.classification_id and(m0.entity_id is null or m0.entity_id=f.entity_id)and(m0.cost_center_id is null or m0.cost_center_id=f.cost_center_id)and f.event_date between m0.effective_from and m0.effective_to order by((m0.entity_id is not null)::int+(m0.cost_center_id is not null)::int)desc,m0.id limit 1)m on true)
select f.financial_line_id,f.event_id,f.organization_id,f.entity_id,f.cost_center_id,f.classification_type,f.event_date,f.month_index,f.status,case when f.unmapped_reason is null then f.selected_line end,case when f.unmapped_reason is null then f.selected_mapping end,case when f.unmapped_reason is null then f.actual_base_amount else 0 end,case when f.unmapped_reason is null then f.committed_base_amount else 0 end,case when f.unmapped_reason is not null then case when f.status='ACTUAL' then f.actual_base_amount else f.committed_base_amount end else 0 end,f.unmapped_reason,f.source_module,f.source_record_id,f.source_event_key,f.base_currency from matches f;$$;
create or replace function public.financial_budget_report(p_plan uuid) returns jsonb language plpgsql stable security definer set search_path='pg_catalog','public','private' as $$declare o public.financial_budget_plan_ownership%rowtype;p public.budget_plans%rowtype;result jsonb;unmapped jsonb;begin select * into o from public.financial_budget_plan_ownership where plan_id=p_plan;if not found or not public.financial_budget_can(o.organization_id,o.entity_id,o.cost_center_id) then raise exception 'BUDGET_PLAN_READ_DENIED';end if;select * into p from public.budget_plans where id=p_plan;with facts as(select * from private.phase2d_plan_facts(p_plan)),monthly as(select bl.id budget_line_id,bl.name,bl.category,bl.line_type,m.month fiscal_month,coalesce(bl.monthly_budget[m.month],0) budget_amount,coalesce(bl.monthly_actual[m.month],0) legacy_actual,coalesce(bl.monthly_forecast[m.month],0) forecast_amount,coalesce((select sum(f.actual_amount) from facts f where f.budget_line_id=bl.id and f.fiscal_month=m.month),0) actual_amount,coalesce((select sum(f.committed_amount) from facts f where f.budget_line_id=bl.id and f.fiscal_month=m.month),0) committed_amount,0::numeric paid_settled_gross,0::numeric outstanding_gross from public.budget_lines bl cross join generate_series(1,12)m(month) where bl.plan_id=p_plan and bl.user_id=p.user_id and bl.active),metrics as(select *,budget_amount-committed_amount-actual_amount remaining_budget,case when line_type='REVENUE' then actual_amount-budget_amount else budget_amount-actual_amount end favorable_variance,forecast_amount-actual_amount forecast_minus_actual,actual_amount-legacy_actual reconciliation_difference from monthly)select coalesce(jsonb_agg(to_jsonb(metrics)||jsonb_build_object('variance_percent',100*favorable_variance/nullif(abs(budget_amount),0),'actual_source','FINANCIAL_CORE_DERIVED','legacy_source','LEGACY_MANUAL_MONTHLY_ACTUAL') order by budget_line_id,fiscal_month),'[]') into result from metrics;select coalesce(jsonb_agg(to_jsonb(f)),'[]') into unmapped from private.phase2d_plan_facts(p_plan)f where f.reason is not null;return jsonb_build_object('plan_id',p_plan,'organization_id',o.organization_id,'entity_id',o.entity_id,'cost_center_id',o.cost_center_id,'currency',p.currency,'scenario',p.scenario,'fiscal_start',o.fiscal_start,'rows',result,'unmapped_financial_actuals',unmapped,'unmapped_amount',(select coalesce(sum(f.unmapped_amount),0)from private.phase2d_plan_facts(p_plan)f where f.reason is not null),'unmapped_alert',jsonb_array_length(unmapped)>0,'legacy_actual_not_replaced',true,'forecast_not_changed',true);end$$;
create or replace function public.financial_budget_drilldown(p_plan uuid) returns setof jsonb language plpgsql stable security definer set search_path='pg_catalog','public','private' as $$declare o public.financial_budget_plan_ownership%rowtype;begin select * into o from public.financial_budget_plan_ownership where plan_id=p_plan;if not found or not public.financial_budget_can(o.organization_id,o.entity_id,o.cost_center_id) then raise exception 'BUDGET_PLAN_READ_DENIED';end if;return query select to_jsonb(f) from private.phase2d_plan_facts(p_plan)f;end$$;
grant execute on function public.financial_budget_report(uuid),public.financial_budget_drilldown(uuid),public.financial_budget_can(uuid,uuid,uuid,boolean) to authenticated;
